require_once dirname(__DIR__,2).'/app/bootstrap.php';require_admin();$fields=['site_name'=>'Website name','site_city'=>'Primary city / region','site_tagline'=>'Short tagline','site_description'=>'Website meta description','hero_title'=>'Homepage headline','hero_subtitle'=>'Homepage introduction','contact_email'=>'Public contact email','contact_phone'=>'Public contact phone','footer_note'=>'Footer message','default_language'=>'Default language (en, hi, bn)','currency'=>'Display currency code (e.g. INR)'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();foreach($fields as $k=>$label){$v=trim((string)($_POST[$k]??''));if(text_len((string)$v)>($k==='site_description'?300:500))continue;if($k==='contact_email'&&$v!==''&&!filter_var($v,FILTER_VALIDATE_EMAIL))continue;if($k==='default_language'&&!in_array($v,['en','hi','bn'],true))continue;if($k==='currency'&&!preg_match('/^[A-Z]{3}$/',$v))continue;save_setting($k,$v);}flash('success','Website settings saved.');redirect(app_path('admin/settings.php'));}$adminTitle='Site settings';include __DIR__.'/_header.php';?>
